import re


def _tokenize(s: str):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/()':
            tokens.append(c)
            i += 1
            continue
        if c.isdigit() or c == '.':
            j = i
            has_dot = False
            while j < n and (s[j].isdigit() or (s[j] == '.' and not has_dot)):
                if s[j] == '.':
                    has_dot = True
                j += 1
            tokens.append(s[i:j])
            i = j
            continue
        raise ValueError(f"Unknown character in expression: {c!r}")
    return tokens


def evaluate(expr: str) -> float:
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")

    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    num_re = re.compile(r'^\d+(\.\d+)?$')

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok == '(':
            advance()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("Unbalanced parentheses: expected ')'")
            advance()
            return val
        elif num_re.match(tok):
            advance()
            return float(tok)
        else:
            raise ValueError(f"Unexpected token: {tok!r}")

    def parse_factor():
        tok = peek()
        if tok == '-':
            advance()
            return -parse_factor()
        else:
            return parse_primary()

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            right = parse_factor()
            if op == '*':
                val *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                val /= right
        return val

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            right = parse_term()
            if op == '+':
                val += right
            else:
                val -= right
        return val

    result = parse_expr()

    if pos[0] != len(tokens):
        raise ValueError(f"Unexpected token at end of expression: {peek()!r}")

    return float(result)
